if record.production_id:
  update_mo = env['mrp.production'].search([('id', '=', record.production_id.id),('company_id', '=', company.id)],limit=1)

  if update_mo:
    mo_vals = {'mass_produced': True, 'serial_cancelled': False}
    # Show the mass-produced serial on the MO instead of letting Odoo
